<?php
namespace App\Tests\Runtime;
use App\Runtime\RuntimePurchaseTaxAudit as A;
use PHPUnit\Framework\TestCase;
final class RuntimePurchaseTaxAuditTest extends TestCase
{
 public static function definition():array{return RuntimePurchaseExpenseAuditTest::definition();}
 public static function endpoint():array{return RuntimePurchaseExpenseAuditTest::endpoint('calculate_taxes');}
 public static function calculation():array{return ['calc_imp_proc_compra_id'=>501,'dt_hr_calculo'=>'2026-10-23T12:00:00.000','usuario_id'=>'real'];}
 public static function body():array{$before=RuntimePurchaseExpenseAuditTest::image();$after=$before;$after['vl_prev']=15.75;$after['calc_imp_proc_compra_id']=501;$created=$after;$created['despesa_proc_compra_id']=102;$created['despesa_id']=8;$created['vl_prev']=23;$h=RuntimePurchaseExpenseAuditTest::header();return ['success'=>true,'committed'=>true,'calculationId'=>501,'created'=>1,'updated'=>1,'data'=>['type'=>'message','message'=>'Cálculo confirmado.'],'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'procs-compra','operation'=>'calculate_taxes','recordId'=>10,'actor'=>['login'=>'real'],'before'=>$h,'after'=>$h,'changes'=>[['resource'=>'calcs-imp-proc-compra','operation'=>'create','recordId'=>501,'before'=>[],'after'=>self::calculation()],['resource'=>'despesas-proc-compra','operation'=>'update','recordId'=>101,'before'=>$before,'after'=>$after],['resource'=>'despesas-proc-compra','operation'=>'create','recordId'=>102,'before'=>[],'after'=>$created]],'warnings'=>[]]];}
 public function testCalculationAndAllExpenseImagesShareAuthenticatedActorOwnerAndCalcId():void{
  self::assertTrue(class_exists(A::class),'Fiscal audit profile not implemented');$a=A::inspect(self::definition(),self::endpoint(),self::body(),['proc_compra_id'=>10],'real');self::assertTrue($a['metadata']['available']);self::assertSame('calculate_taxes',$a['metadata']['operation']);self::assertSame(501,$a['metadata']['calculationId']);self::assertCount(3,$a['events']);self::assertSame('calcs_imp_proc_compra',$a['events'][0]['metadata']['resource']);self::assertSame(self::calculation(),$a['events'][0]['after']);self::assertSame(12.5,$a['events'][1]['before']['vl_prev']);self::assertSame(15.75,$a['events'][1]['after']['vl_prev']);self::assertSame(0,$a['events'][1]['before']['calc_imp_proc_compra_id']);self::assertSame(501,$a['events'][1]['after']['calc_imp_proc_compra_id']);self::assertSame([],$a['events'][2]['before']);
 }
 public function testTamperedUnconfirmedWrongActorAndCrossProcessReceiptsCannotProduceConfirmedEvents():void{
  foreach(['commit','actor','calc-actor','calc-id','missing-calc','duplicate-calc','unknown-calc-field','parent-change','context','foreign-owner','changed-definition','changed-identity','wrong-calc','update-absent','create-present','duplicate-id','duplicate-definition','extra-effect-field','delete-effect','created-count','updated-count','fractional-amount','legacy-operation','browser-source','typed-owner']as$case){$b=self::body();$context=['proc_compra_id'=>10];switch($case){case'commit':$b['committed']=false;break;case'actor':$b['audit']['actor']['login']='fake';break;case'calc-actor':$b['audit']['changes'][0]['after']['usuario_id']='fake';break;case'calc-id':$b['calculationId']=502;break;case'missing-calc':array_shift($b['audit']['changes']);break;case'duplicate-calc':$b['audit']['changes'][]=$b['audit']['changes'][0];break;case'unknown-calc-field':$b['audit']['changes'][0]['after']['proc_compra_id']=10;break;case'parent-change':$b['audit']['after']['observacao']='bad';break;case'context':$context['item_proc_compra_id']=11;break;case'foreign-owner':$b['audit']['changes'][1]['after']['proc_compra_id']=20;break;case'changed-definition':$b['audit']['changes'][1]['after']['despesa_id']=9;break;case'changed-identity':$b['audit']['changes'][1]['after']['despesa_proc_compra_id']=999;break;case'wrong-calc':$b['audit']['changes'][2]['after']['calc_imp_proc_compra_id']=502;break;case'update-absent':$b['audit']['changes'][1]['before']=[];break;case'create-present':$b['audit']['changes'][2]['before']=$b['audit']['changes'][2]['after'];break;case'duplicate-id':$b['audit']['changes'][2]['recordId']=101;$b['audit']['changes'][2]['after']['despesa_proc_compra_id']=101;break;case'duplicate-definition':$b['audit']['changes'][2]['after']['despesa_id']=7;break;case'extra-effect-field':$b['audit']['changes'][1]['sql']='bad';break;case'delete-effect':$b['audit']['changes'][1]['operation']='delete';break;case'created-count':$b['created']=2;break;case'updated-count':$b['updated']=2;break;case'fractional-amount':$b['audit']['changes'][1]['after']['vl_prev']=15.751;break;case'legacy-operation':$b['audit']['operation']='generate';break;case'browser-source':$b['audit']['source']='browser';break;case'typed-owner':$context['proc_compra_id']='10';break;}$a=A::inspect(self::definition(),self::endpoint(),$b,$context,'real');self::assertFalse($a['metadata']['available'],$case);self::assertSame([],$a['events'],$case);}
 }
 public function testBindingIsFixedToRegisteredFiscalOperationAndMed():void{
  foreach(['operation','method','host','context','resource']as$case){$e=self::endpoint();switch($case){case'operation':$e['bodyTemplate']['operation']='generate';break;case'method':$e['method']='GET';break;case'host':$e['url']='http://evil/SursumPrograms/ciw-cadastros';break;case'context':$e['requestContextFields'][]='empresa_id';break;case'resource':$e['bodyTemplate']['resource']='other';break;}self::assertFalse(A::inspect(self::definition(),$e,self::body(),['proc_compra_id'=>10],'real')['metadata']['available'],$case);}
 }
 public function testNoRootTaxesStillImportsOnlyNewPhysicalCalculationAndParent():void{
  $b=self::body();$b['created']=0;$b['updated']=0;$b['audit']['changes']=[$b['audit']['changes'][0]];$a=A::inspect(self::definition(),self::endpoint(),$b,['proc_compra_id'=>10],'real');self::assertTrue($a['metadata']['available']);self::assertCount(1,$a['events']);
 }
}
